	"AUTH_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                             
	"AUTH_NAME" NVARCHAR2(64) NOT NULL ENABLE,                                                                                                                                                                          
	"JOB_NUMBER" NVARCHAR2(20),                                                                                                                                                                                         
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                                 
